const $=s=>document.querySelector(s);const dialog=$('#dialog');let opener;function show(title,body,status='SVS Group of Institutions'){opener=document.activeElement;$('#dialog-content').innerHTML=`<span class="status">${status}</span><h2>${title}</h2>${body}`;dialog.showModal()}$('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const campuses={medical:{name:'The Medical Core',intro:'The medical college and teaching hospital share the first compound, bringing academic and clinical spaces together.',tags:['Medical college','Teaching hospital','Independent mess','Separate hostels'],location:'Medical Core ⇄ Opposite: Nursing Campus'},nursing:{name:'The nursing campus',intro:'Located opposite the medical compound, the nursing college and hospital have their own clinical learning and residential facilities.',tags:['Nursing college & hospital','Clinical labs & wards','Independent mess','Dedicated hostels'],location:'Nursing Campus ⇄ Opposite: Medical Core'},dental:{name:'The dental campus',intro:'The dental college and clinics form a separate campus area, with staff quarters opposite. This compound is approximately 1 km from the nursing area.',tags:['Dental college & clinics','Own dining','Student hostels','Staff quarters opposite'],location:'Nursing Campus · Approx. 1 km · Dental & Staff Campus'}};
function campus(key){const c=campuses[key];$('#campus-panel').innerHTML=`${key==='medical'||key==='nursing'?`<img class="campus-photo" loading="lazy" src="assets/${key}-campus.webp" alt="${key==='medical'?'SVS Medical College entrance':'SVS College of Nursing entrance'}">`:''}<div class="eyebrow">CAMPUS GUIDE</div><h3>${c.name}</h3><p>${c.intro}</p><div class="facility-tags">${c.tags.map(x=>`<span>${x}</span>`).join('')}</div><div class="campus-map">⌖ ${c.location}</div>`;document.querySelectorAll('[data-campus]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.campus===key);b.tabIndex=b.dataset.campus===key?0:-1;b.setAttribute('aria-controls','campus-panel')})}if($('#campus-panel'))campus('medical');document.querySelectorAll('[data-campus]').forEach(b=>{b.onclick=()=>campus(b.dataset.campus);b.onkeydown=e=>{if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft'].includes(e.key)){e.preventDefault();const keys=Object.keys(campuses),i=keys.indexOf(b.dataset.campus),next=keys[(i+(e.key==='ArrowRight'||e.key==='ArrowDown'?1:2))%3];campus(next);document.querySelector(`[data-campus="${next}"]`).focus()}}});
const details={medical:['SVS Medical College','Medical education connected to the teaching hospital, with independent dining and separate hostels.',['Programmes & sanctioned intake','Department and faculty directory','Leadership, committees and academic calendar','Research and clinical learning']],dental:['SVS Dental College','A dedicated dental college and clinics, with their own dining and hostel facilities.',['Dental programmes & sanctioned intake','Department and faculty directory','Clinical facilities','Council approvals and affiliation']],nursing:['SVS Nursing College','A nursing college and hospital with dedicated clinical labs, wards, dining and hostels.',['Nursing programmes & sanctioned intake','Faculty and academic leadership','Clinical learning facilities','Council approvals and affiliation']]};document.querySelectorAll('[data-institution]').forEach(b=>b.onclick=()=>{const [title,intro,items]=details[b.dataset.institution];show(title,`<p>${intro}</p><h3>Information centre</h3><ul>${items.map(x=>`<li>${x} — awaiting verified institutional content.</li>`).join('')}</ul><p>Programme eligibility, fees, seats, admission dates and recognition will be displayed only after institutional verification.</p><a class="button" href="admissions.html" onclick="document.querySelector('dialog').close()">Explore admissions ↗</a>`) });
document.querySelectorAll('[data-portal]').forEach(b=>b.onclick=()=>show(b.dataset.portal,'<p>For portal access and account assistance, contact the college office. Online account access is not available through this website.</p><p><a href="tel:08542227902">08542-227902</a> · <a href="mailto:svsmc_mbnr@yahoo.co.in">svsmc_mbnr@yahoo.co.in</a></p>','College services'));
